-- Envoy (CORE_T1_SEA_Envoy): Lua unit script generated by tools/s3okit/kit/cob2lus.py from CORE_T1_SEA_Envoy.COB.
-- cob2lus body sha1: ba3607599600
turret, door1, door2, door3, magnet, boom, arm1, arm2 = piece('turret', 'door1', 'door2', 'door3', 'magnet', 'boom', 'arm1', 'arm2')
arm3, arm4, arm5, wake1, wake2, base, link = piece('arm3', 'arm4', 'arm5', 'wake1', 'wake2', 'base', 'link')

include "smokeunit.lua"

local AttachUnit = Spring.UnitScript.AttachUnit
local DropUnit = Spring.UnitScript.DropUnit
local rad = math.rad
local floor = math.floor
local COB2RAD = math.pi / 32768
local SIG_MOVE = 1
local SIG_STARTDOOROPEN = 2
local s0 = 0
local s1 = 0
local s2 = 0
local s3 = 0

local function Blow(list, flags)
	for _, p in ipairs(list) do Explode(p, flags) end
end

local function BoomCalc(a0, a1)
	local l2 = 0
	local l3 = 0
	local l4 = 0
	l2 = GetUnitValue(COB.PIECE_XZ, turret - 1) - a0
	l3 = a1 - GetUnitValue(COB.PIECE_Y, turret - 1) - 3276800
	l4 = GetUnitValue(COB.XZ_HYPOT, l2)
	s0 = GetUnitValue(COB.HYPOT, l4, l3) - 3276800
	s1 = GetUnitValue(COB.XZ_ATAN, l2)
	s2 = GetUnitValue(COB.ATAN, l3, l4)
	s3 = s0 < 21504000 and 1 or 0
end

local function StartDoorOpen()
	Signal(SIG_STARTDOOROPEN)
	SetSignalMask(SIG_STARTDOOROPEN)
	Move(door1, z_axis, -15, 25)
	Move(door2, z_axis, -15, 25)
	Move(door3, z_axis, -15, 25)
	Sleep(5000)
	Move(door1, z_axis, 0, 25)
	Move(door2, z_axis, 0, 25)
	Move(door3, z_axis, 0, 25)
end

local function BoomExtend()
	local l0 = 0
	local l1 = 0
	StartThread(StartDoorOpen)
	Turn(turret, y_axis, s1 * COB2RAD, rad(149.96))
	Turn(magnet, x_axis, s2 * COB2RAD, rad(59.99))
	Turn(boom, x_axis, -(s2 * COB2RAD), rad(59.99))
	Move(arm1, z_axis, math.min(floor(s0 / 5) / 65536, 31), 150)
	Move(arm2, z_axis, math.min(floor(s0 / 5) / 65536, 31), 150)
	Move(arm3, z_axis, math.min(floor(s0 / 5) / 65536, 31), 150)
	Move(arm4, z_axis, math.min(floor(s0 / 5) / 65536, 31), 150)
	Move(arm5, z_axis, math.min(floor(s0 / 5) / 65536, 31), 150)
	WaitForTurn(turret, y_axis)
	WaitForTurn(boom, x_axis)
	WaitForMove(arm1, z_axis)
	WaitForMove(arm2, z_axis)
	WaitForMove(arm3, z_axis)
	WaitForMove(arm4, z_axis)
	WaitForMove(arm5, z_axis)
end

local function BoomToPad()
	StartThread(StartDoorOpen)
	Turn(turret, y_axis, 0, rad(149.96))
	Turn(magnet, x_axis, 0, rad(59.99))
	Turn(boom, x_axis, 0, rad(59.99))
	Move(arm1, z_axis, 0, 150)
	Move(arm2, z_axis, 0, 150)
	Move(arm3, z_axis, 0, 150)
	Move(arm4, z_axis, 0, 150)
	Move(arm5, z_axis, 0, 150)
	WaitForTurn(turret, y_axis)
	WaitForTurn(boom, x_axis)
	WaitForMove(arm1, z_axis)
	WaitForMove(arm2, z_axis)
	WaitForMove(arm3, z_axis)
	WaitForMove(arm4, z_axis)
	WaitForMove(arm5, z_axis)
	Turn(magnet, x_axis, rad(-29.99), rad(59.99))
	Turn(boom, x_axis, rad(29.99), rad(59.99))
	WaitForTurn(boom, x_axis)
end

local function BoomReset()
	Turn(turret, y_axis, 0, rad(99.98))
	Turn(magnet, x_axis, 0, rad(39.99))
	Turn(boom, x_axis, 0, rad(39.99))
	Move(arm1, z_axis, 0, 112.5)
	Move(arm2, z_axis, 0, 112.5)
	Move(arm3, z_axis, 0, 112.5)
	Move(arm4, z_axis, 0, 112.5)
	Move(arm5, z_axis, 0, 112.5)
end

function script.Create()
	StartThread(SmokeUnit, {base})
end

local function StartMoving()
	Signal(SIG_MOVE)
	SetSignalMask(SIG_MOVE)
	while true do
		EmitSfx(wake1, 2)
		EmitSfx(wake2, 2)
		Sleep(300)
	end
end

function script.StartMoving()
	StartThread(StartMoving)
end

function script.StopMoving()
	Signal(SIG_MOVE)
end

function script.SweetSpot()
	return base
end

-- how far the boom's tip misses a point along the boom (kit model lengths, the arm travel limit): the empty link makes up the rest
local function ReachOffset(xz)
	local root = GetUnitValue(COB.PIECE_XZ, turret - 1)
	Move(link, z_axis, 0)
	return (GetUnitValue(COB.XZ_HYPOT, root - xz) - GetUnitValue(COB.XZ_HYPOT, root - GetUnitValue(COB.PIECE_XZ, link - 1))) / 65536
end

-- the cargo stays where it stands when it is grabbed, instead of jumping to the boom's tip and into the ground
local function ReachCargo(unitid)
	Move(link, z_axis, ReachOffset(GetUnitValue(COB.UNIT_XZ, unitid)))
	Move(link, y_axis, 0)
	Move(link, y_axis, (GetUnitValue(COB.UNIT_Y, unitid) - GetUnitValue(COB.PIECE_Y, link - 1)) / 65536)
end

function script.TransportPickup(unitid)
	BoomCalc(GetUnitValue(COB.UNIT_XZ, unitid), GetUnitValue(COB.UNIT_Y, unitid) + GetUnitValue(COB.UNIT_HEIGHT, unitid))
	if s3 ~= 0 then
		SetUnitValue(COB.BUSY, 1)
		BoomExtend()
		ReachCargo(unitid)
		AttachUnit(link, unitid)
		Move(link, z_axis, 0, 150)
		BoomToPad()
		AttachUnit(0, unitid)
		BoomReset()
		SetUnitValue(COB.BUSY, 0)
	end
end

function script.TransportDrop(unitid, x, y, z)
	local pos = floor(x) * 65536 + floor(z) % 65536   -- COB gets the drop point as PACKXZ
	BoomCalc(pos, GetUnitValue(COB.GROUND_HEIGHT, pos) + GetUnitValue(COB.UNIT_HEIGHT, unitid))
	if s3 ~= 0 then
		SetUnitValue(COB.BUSY, 1)
		BoomToPad()
		Move(link, y_axis, (0 - GetUnitValue(COB.UNIT_HEIGHT, unitid)) / 65536)
		AttachUnit(link, unitid)
		BoomExtend()
		-- the cargo comes down on the chosen spot, not short of it and under the ground
		Move(link, z_axis, ReachOffset(pos), 150)
		Move(link, y_axis, (GetUnitValue(COB.GROUND_HEIGHT, pos) - GetUnitValue(COB.PIECE_Y, link - 1) - GetUnitValue(COB.UNIT_HEIGHT, unitid)) / 65536, 150)
		WaitForMove(link, z_axis)
		WaitForMove(link, y_axis)
		DropUnit(unitid)
		Move(link, z_axis, 0)
		BoomReset()
		SetUnitValue(COB.BUSY, 0)
	end
end

function script.Killed(recentDamage, maxHealth)
	local severity = recentDamage / maxHealth * 100
	if severity <= 25 then
		Explode(boom, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({arm1, arm2, base, door1, door2}, SFX.NONE)
		Explode(link, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({turret, wake1, wake2}, SFX.NONE)
		return 1
	end
	if severity <= 50 then
		Explode(boom, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({arm1, arm2}, SFX.SHATTER)
		Blow({base, door1, door2}, SFX.NONE)
		Explode(link, SFX.FALL + SFX.NO_HEATCLOUD)
		Explode(turret, SFX.NONE)
		Blow({wake1, wake2}, SFX.FALL)
		return 2
	end
	if severity <= 99 then
		Explode(boom, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({arm1, arm2}, SFX.SHATTER)
		Blow({base, door1, door2}, SFX.NONE)
		Explode(link, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
		Explode(turret, SFX.NONE)
		Blow({wake1, wake2}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
		return 2
	end
	Explode(boom, SFX.NONE + SFX.NO_HEATCLOUD)
	Explode(arm1, SFX.SHATTER + SFX.EXPLODE_ON_HIT)
	Explode(arm2, SFX.SHATTER)
	Blow({base, door1, door2}, SFX.NONE)
	Explode(link, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
	Explode(turret, SFX.NONE)
	Blow({wake1, wake2}, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE)
	return 2
end
